create or replace function public.get_developer_agency_guard_credentials_rc1(p_agency_id uuid) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; return coalesce((select jsonb_agg(to_jsonb(gc) order by gc.created_at desc) from public.guard_credentials gc join public.guards g on g.id=gc.guard_id where g.agency_id=p_agency_id),'[]'::jsonb); end; $$;
create or replace function public.submit_developer_guard_qualification_rc1(p_agency_id uuid,p_guard_id uuid,p_credential_type text,p_license_number text,p_jurisdiction text,p_expires_on date default null) returns jsonb language plpgsql security definer set search_path=public set row_security=off as $$ declare v_id uuid; begin if auth.uid() is null or public.current_role()<>'platform_admin'::public.app_role then raise exception 'PLATFORM_ADMIN_REQUIRED' using errcode='42501'; end if; if p_credential_type not in('security_officer','armed_qualification') then raise exception 'INVALID_CREDENTIAL_TYPE'; end if; if nullif(trim(p_license_number),'') is null then raise exception 'LICENSE_NUMBER_REQUIRED'; end if; if not exists(select 1 from public.guards where id=p_guard_id and agency_id=p_agency_id and agency_approved=true) then raise exception 'GUARD_NOT_APPROVED_BY_AGENCY' using errcode='42501'; end if; insert into public.guard_credentials(guard_id,credential_type,license_number,jurisdiction,expires_on,verification_status,verified_at,verified_by) values(p_guard_id,p_credential_type,trim(p_license_number),upper(trim(coalesce(nullif(p_jurisdiction,''),'FL'))),p_expires_on,'verified',now(),auth.uid()) on conflict(guard_id,credential_type,jurisdiction) do update set license_number=excluded.license_number,expires_on=excluded.expires_on,verification_status='verified',verified_at=now(),verified_by=auth.uid(),updated_at=now() returning id into v_id; return jsonb_build_object('id',v_id,'guard_id',p_guard_id,'agency_id',p_agency_id,'verification_status','verified'); end; $$;
revoke all on function public.get_developer_agency_guard_credentials_rc1(uuid) from public,anon;
revoke all on function public.submit_developer_guard_qualification_rc1(uuid,uuid,text,text,text,date) from public,anon;
grant execute on function public.get_developer_agency_guard_credentials_rc1(uuid) to authenticated,service_role;
grant execute on function public.submit_developer_guard_qualification_rc1(uuid,uuid,text,text,text,date) to authenticated,service_role;
